package com.zoro.zoromart.dao;
import java.sql.*;import java.util.*;
/** JDBC persistence for user accounts. All SQL is parameterized. */
public class UserDAO {private final Connection c;public UserDAO(Connection c){this.c=c;}public Map<String,Object> byEmail(String email)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id,name,email,password_hash,role FROM users WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("name",r.getString("name"));m.put("email",r.getString("email"));m.put("passwordHash",r.getString("password_hash"));m.put("role",r.getString("role"));return m;}}}public long create(String name,String email,String hash,String role)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,hash);p.setString(4,role);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}public List<Map<String,Object>> all()throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT id,name,email,role,created_at FROM users ORDER BY id DESC");ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong(1));m.put("name",r.getString(2));m.put("email",r.getString(3));m.put("role",r.getString(4));m.put("createdAt",r.getTimestamp(5).toString());a.add(m);}}return a;}}
